local function evalDependencyRpn(rpn, values)
    if not rpn or #rpn == 0 then
        return true
    end

    local stack = {}
    for i = 1, #rpn do
        local tok = rpn[i]
        if tok.type == "id" then
            stack[#stack + 1] = not not values[tok.value]
        elseif tok.type == "op" then
            if tok.value == "not" then
                local a = stack[#stack]
                stack[#stack] = not a
            else
                local b = stack[#stack]
                stack[#stack] = nil
                local a = stack[#stack]
                stack[#stack] = nil
                if tok.value == "and" then
                    stack[#stack + 1] = a and b
                else
                    stack[#stack + 1] = a or b
                end
            end
        end
    end

    return not not stack[1]
end

function mainTable.fieldVisible(slot, values)
    local field = mainTable.fieldsBySlot[slot]
