    values = values or {}
    return evalDependencyRpn(field.dependencyRpn, values)
end

function mainTable.runCommand(slot, ...)
    local field = mainTable.fieldsBySlot[slot]
    if not field then
        return nil, "Unknown slot"
    end

    local cmd = field.command
    if cmd == "" or cmd == "none" then
        return nil
    end
    if cmd == "update" then
        return true
    end

    local fn = mainTable.commands[cmd]
    if not fn then
        return nil, "Missing compiled command: " .. tostring(cmd)
    end

    return fn(...)
end

function mainTable.updateDependency(symbol, context)
    local targets = mainTable.reverseDeps[symbol] or {}
